fn solve(n: i8, m: i8) -> i8 {
    // Number of mixed groups is limited by n and floor(m/2)
    let mixed = n.min(m / 2);
    // Consume 2 units of resource 2 for each mixed group
    let remaining = m - mixed * 2;
    // Form pure groups with leftover resource 2 (4 units each)
    let pure = remaining / 4;
    mixed + pure
}

